local BindableIndex = {
	_BindableEvent = nil :: BindableEvent,
	_BindedIndexes = nil :: {[any]: (...any)-> ()?}
}

BindableIndex.__index = BindableIndex

export type BindableIndex = typeof(BindableIndex)

local GlobalIndex = `NOTEKAMI_{script}`
if _G[GlobalIndex] then
	return _G[GlobalIndex] :: BindableIndex
end

function BindableIndex.Connect(self: BindableIndex, Index: any, Method: (...any)-> ()?)
	self._BindedIndexes[Index] = Method
end

function BindableIndex.Once(self: BindableIndex, Index: any, Method: (...any)-> ()?)
	self._BindedIndexes[Index] = function(...)
		self:Disconnect(Index)
		return Method(...)
	end
end

function BindableIndex.Disconnect(self: BindableIndex, Index: any, ...:any?)
	self:Connect(Index)
end

function BindableIndex.Fires(self: BindableIndex, Index: any, ...:any?)
	self:GetInstance():Fire(Index, ...)
end

function BindableIndex.GetInstance(self: BindableIndex): BindableEvent
	return self._BindableEvent
end

function BindableIndex.Destroy(self: BindableIndex): ()
	self:GetInstance():Destroy()
	setmetatable(self, nil)
end

local Module = table.freeze{
	New = function(): BindableIndex

		local self = setmetatable({ _BindedIndexes = {} }, BindableIndex) :: BindableIndex
		local BindableEvent = Instance.new(`BindableEvent`)
		BindableEvent.Event:Connect(function(Index: any, ...)
			return self._BindedIndexes[Index] and self._BindedIndexes[Index](...) or nil
		end)

		self._BindableEvent = BindableEvent

		return self
	end,
}

_G[GlobalIndex] = Module

return Module

