local Module = {}
local Error = {}

export type ErrorHandler = typeof(Module)
export type Error = typeof(Error)

local GlobalIndex = `NOTEKAMI_{script}`
if _G[GlobalIndex] then
	return _G[GlobalIndex] :: ErrorHandler
else
	_G[GlobalIndex] = Module
end

do
	do
		Module.__index = Module
		Module.Kind = {
			ExecutionError = "ExecutionError",
			AlreadyCancelled = "AlreadyCancelled",
			NotResolvedInTime = "NotResolvedInTime",
			TimedOut = "TimedOut",
		}
	end

	function Module.New(Options, Parent)
		Options = Options or {}
		return setmetatable({
			Error = `{Options.Error}` or "[This error has no error text]",
			Trace = Options.Trace,
			Context = Options.Context,
			Kind = Options.Kind,
			Parent = Parent,
			CreatedTick = os.clock(),
			CreatedTrace = debug.traceback(),
		}, Module)
	end

	function Module.Is(Anything)
		return getmetatable(Anything) == Error
	end

	function Error.Extend(self: Error, Options)
		Options = Options or {}
		Options.Kind = Options.Kind or self.Kind
		return Module.New(Options, self)
	end

	function Module.GetErrorChain(self: Error)
		local RuntimeErrors = {self}

		while RuntimeErrors[#RuntimeErrors].Parent do
			table.insert(RuntimeErrors, RuntimeErrors[#RuntimeErrors].Parent)
		end

		return RuntimeErrors
	end

	function Module.__tostring(self: Error)
		local ErrorStrings = {
			string.format("-- Promise.Error(%s) --", self.Kind or "?"),
		}

		for _, RuntimeError in self:GetErrorChain() do
			table.insert(
				ErrorStrings,
				table.concat({
					RuntimeError.Trace or RuntimeError.Error,
					RuntimeError.Context,
				}, "\n")
			)
		end

		return table.concat(ErrorStrings, "\n")
	end
end

return Module

--[[
	❗ When using this module, you should understand that at the bytecode level it works slower than the global version ❗
]]

local Module = {}

export type buffer = typeof(Module) & typeof(buffer)

local BufferEncoder = require(script:WaitForChild(`BufferEncoder`))

do type([[ Copying from buffer table ]])
	for I, V in buffer do
		Module[I] = V
	end
end

--[[
	Pack everything to buffer
]]
function Module.pack(...: any)
	return BufferEncoder.write({...}, nil, true, true) --Converter.write({...})
end

--[[
	Unpack buffer from buffer.pack
]]
function Module.unpack(Buffer, Referense: {Instance})
	return table.unpack(BufferEncoder.read(Buffer, nil, Referense, true))
end

Module.serializate = Module.pack
Module.deserialization = Module.unpack

return table.freeze(Module) :: buffer

